export function getTranslatedCaterpillarSparePartDetails(partName: string, language: string = 'zh'): string {
  const canonicalName = caterpillarDetailSourceNameAliases[partName] || partName;
  const details = caterpillarPartDetailsTranslations[canonicalName as keyof typeof caterpillarPartDetailsTranslations];
  return details?.[language as keyof typeof details] || 'OEM quality part. Contact us for detailed specifications and pricing.';
}
